class StateOfTicTacToe {
    public GameState determineState(String[] board) {
        int xCount = 0;
        int oCount = 0;
        for (String row : board) {
            for (char c : row.toCharArray()) {
                if (c == 'X') {
                    xCount++;
                } else if (c == 'O') {
                    oCount++;
                }
            }
        }

        if (xCount < oCount) {
            throw new IllegalArgumentException("Wrong turn order: O started");
        }
        if (xCount > oCount + 1) {
            throw new IllegalArgumentException("Wrong turn order: X went twice");
        }

        boolean xWon = hasWon(board, 'X');
        boolean oWon = hasWon(board, 'O');

        if (xWon && oWon) {
            throw new IllegalArgumentException("Impossible board: game should have ended after the game was won");
        }
        if (xWon && xCount != oCount + 1) {
            throw new IllegalArgumentException("Impossible board: game should have ended after the game was won");
        }
        if (oWon && xCount != oCount) {
            throw new IllegalArgumentException("Impossible board: game should have ended after the game was won");
        }

        if (xWon || oWon) {
            return GameState.WIN;
        }
        if (xCount + oCount == 9) {
            return GameState.DRAW;
        }
        return GameState.ONGOING;
    }

    private boolean hasWon(String[] board, char mark) {
        for (int i = 0; i < 3; i++) {
            if (board[i].charAt(0) == mark && board[i].charAt(1) == mark && board[i].charAt(2) == mark) {
                return true;
            }
            if (board[0].charAt(i) == mark && board[1].charAt(i) == mark && board[2].charAt(i) == mark) {
                return true;
            }
        }
        if (board[0].charAt(0) == mark && board[1].charAt(1) == mark && board[2].charAt(2) == mark) {
            return true;
        }
        if (board[0].charAt(2) == mark && board[1].charAt(1) == mark && board[2].charAt(0) == mark) {
            return true;
        }
        return false;
    }
}
